import 'package:flutter/material.dart';
void main()=>runApp(const CampusApp());
class CampusApp extends StatelessWidget{const CampusApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Campus Companion',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:Colors.indigo),useMaterial3:true),home:const Dashboard());}
class Dashboard extends StatefulWidget{const Dashboard({super.key});@override State<Dashboard> createState()=>_DashboardState();}
class _DashboardState extends State<Dashboard>{int tab=0;bool reminders=true;String year='Second Year';final name=TextEditingController();@override void dispose(){name.dispose();super.dispose();}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Campus Companion'),actions:[IconButton(onPressed:()=>ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('You are all caught up!'))),icon:const Icon(Icons.notifications_none))]),body:ListView(padding:const EdgeInsets.all(18),children:[Text('Good afternoon 👋',style:Theme.of(c).textTheme.headlineMedium),const Text('Your student life, in one place.'),const SizedBox(height:18),GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,childAspectRatio:1.6,crossAxisSpacing:10,mainAxisSpacing:10,children:const [ _Tile(Icons.calendar_month,'Timetable','4 classes today'),_Tile(Icons.assignment,'Assignments','2 due this week'),_Tile(Icons.groups,'Clubs','3 active clubs'),_Tile(Icons.school,'Attendance','92% this month')]),const SizedBox(height:18),const Text('Student profile',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),TextField(controller:name,decoration:const InputDecoration(labelText:'Your name',border:OutlineInputBorder(),prefixIcon:Icon(Icons.person))),const SizedBox(height:10),DropdownButtonFormField(value:year,decoration:const InputDecoration(labelText:'Academic year',border:OutlineInputBorder()),items:const ['First Year','Second Year','Third Year','Final Year'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>year=v??year)),SwitchListTile(title:const Text('Enable assignment reminders'),value:reminders,onChanged:(v)=>setState(()=>reminders=v)),FilledButton(onPressed:()=>ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text('Profile saved for ${name.text.isEmpty?"student":name.text} • $year'))),child:const Text('Save profile'))]),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),label:'Home'),NavigationDestination(icon:Icon(Icons.event),label:'Events'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Profile')]));}}
class _Tile extends StatelessWidget{final IconData icon;final String title,sub;const _Tile(this.icon,this.title,this.sub);@override Widget build(BuildContext c)=>Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.center,children:[Icon(icon,size:28),const SizedBox(height:7),Text(title,style:const TextStyle(fontWeight:FontWeight.bold)),Text(sub,style:Theme.of(c).textTheme.bodySmall)])));}
